package net.wolfig.codeowls.statusbar;

import com.intellij.openapi.components.Service;
import com.intellij.openapi.editor.Document;
import com.intellij.openapi.fileEditor.FileDocumentManager;
import com.intellij.openapi.project.Project;
import com.intellij.openapi.vfs.VirtualFile;
import net.wolfig.codeowls.explain.OwnershipExplanation;
import net.wolfig.codeowls.matcher.CodeownersRule;
import net.wolfig.codeowls.matcher.CodeownersRuleParser;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;

/**
 * Project-level service that locates the active CODEOWNERS file, parses it
 * into rules (cached by modification stamp), and resolves the matching rule
 * for a given file using last-match-wins semantics.
 *
 * <p>The service is intentionally listener-free: it reparses lazily when a
 * caller asks for rules and the cached document/file stamp has changed. The
 * widget owns its own VFS / PSI listeners and drives re-resolution; centralizing
 * cache-invalidation that way avoids a feedback loop between service and UI.
 *
 * <p>For a given file the service walks up its parent chain looking for
 * {@code .github/CODEOWNERS}, {@code CODEOWNERS}, {@code docs/CODEOWNERS}, and
 * {@code .gitlab/CODEOWNERS} (GitHub's documented precedence, plus the GitLab
 * location). The first hit wins, which makes monorepos with per-module
 * CODEOWNERS files behave the way {@code git} does and keeps the lookup
 * independent of how the project's content roots happen to be registered.
 */
@Service(Service.Level.PROJECT)
public final class CodeownersService {

  private static final String[] CANDIDATE_PATHS = {
          ".github/CODEOWNERS",
          "CODEOWNERS",
          "docs/CODEOWNERS",
          ".gitlab/CODEOWNERS",
  };

  private final Project project;

  /**
   * Snapshot of the last parse. {@code null} means "not yet parsed".
   */
  private volatile Cache cache;

  public CodeownersService(@NotNull Project project) {
    this.project = project;
  }

  public static @NotNull CodeownersService getInstance(@NotNull Project project) {
    return project.getService(CodeownersService.class);
  }

  private static @Nullable Located locateFor(@NotNull VirtualFile file) {
    VirtualFile dir = file.isDirectory() ? file : file.getParent();
    while (dir != null) {
      for (String candidate : CANDIDATE_PATHS) {
        VirtualFile vf = dir.findFileByRelativePath(candidate);
        if (vf != null && vf.isValid() && !vf.isDirectory()) {
          return new Located(vf, dir);
        }
      }
      dir = dir.getParent();
    }
    return null;
  }

  private static @Nullable String relativizeAgainst(@NotNull String filePath, @NotNull String rootPath) {
    if (filePath.equals(rootPath)) return "";
    String prefix = rootPath.endsWith("/") ? rootPath : rootPath + "/";
    if (!filePath.startsWith(prefix)) return null;
    return filePath.substring(prefix.length());
  }

  /**
   * The rules that match {@code relativePath}, in file (evaluation) order. The
   * single source of truth for "which rules apply" — both resolution and
   * explanation go through here so they cannot disagree.
   */
  private static @NotNull List<CodeownersRule> matchingRules(@NotNull List<CodeownersRule> rules,
                                                             @NotNull String relativePath) {
    List<CodeownersRule> matching = new ArrayList<>();
    for (CodeownersRule rule : rules) {
      if (rule.matches(relativePath)) matching.add(rule);
    }
    return matching;
  }

  /**
   * Returns the owners that apply to {@code file} (last matching rule wins),
   * or {@link CodeownersOwnerResolution#NONE} if no rule applies or no
   * CODEOWNERS file is reachable from {@code file}'s ancestors.
   *
   * <p>Must be called under a read action — it accesses VFS and possibly
   * document state.
   */
  public @NotNull CodeownersOwnerResolution resolveOwners(@Nullable VirtualFile file) {
    if (file == null || project.isDisposed()) return CodeownersOwnerResolution.NONE;
    Located located = locateFor(file);
    if (located == null) return CodeownersOwnerResolution.NONE;
    String relativePath = relativizeAgainst(file.getPath(), located.root.getPath());
    if (relativePath == null) return CodeownersOwnerResolution.NONE;

    List<CodeownersRule> matching = matchingRules(getRules(located.codeownersFile), relativePath);
    // Last-match-wins: the last matching rule in file order governs.
    return matching.isEmpty()
            ? CodeownersOwnerResolution.NONE
            : new CodeownersOwnerResolution(matching.get(matching.size() - 1));
  }

  /**
   * Explains the CODEOWNERS ownership of {@code file}: every rule that matches
   * it (in evaluation order) and which one wins. Shares its matching pass with
   * {@link #resolveOwners} via {@link #matchingRules}, so the effective owner in
   * the returned {@link OwnershipExplanation} always agrees with the status bar
   * widget and owner-lookup logic.
   *
   * <p>Must be called under a read action — it accesses VFS and possibly
   * document state.
   */
  public @NotNull OwnershipExplanation explain(@NotNull VirtualFile file) {
    if (project.isDisposed()) return OwnershipExplanation.noCodeowners(file);
    Located located = locateFor(file);
    if (located == null) return OwnershipExplanation.noCodeowners(file);
    String relativePath = relativizeAgainst(file.getPath(), located.root.getPath());
    if (relativePath == null) return OwnershipExplanation.noCodeowners(file);

    List<CodeownersRule> matching = matchingRules(getRules(located.codeownersFile), relativePath);
    return OwnershipExplanation.of(file, relativePath, located.codeownersFile, matching);
  }

  /**
   * Resolves the CODEOWNERS context for {@code file}: the governing CODEOWNERS
   * file, the file's path relative to that CODEOWNERS file's root, and the
   * parsed rules. Returns {@code null} when no CODEOWNERS file is reachable.
   *
   * <p>Used by owner-suggestion: it needs the repo-relative path (to build a
   * new rule and to score path proximity) and the rules, all anchored to the
   * same root the resolver uses. Must be called under a read action.
   */
  public @Nullable FileContext fileContext(@Nullable VirtualFile file) {
    if (file == null || project.isDisposed()) return null;
    Located located = locateFor(file);
    if (located == null) return null;
    String relativePath = relativizeAgainst(file.getPath(), located.root.getPath());
    if (relativePath == null || relativePath.isEmpty()) return null;
    return new FileContext(located.codeownersFile, relativePath, getRules(located.codeownersFile));
  }

  /**
   * @return the CODEOWNERS file that was used for the most recent resolution, or {@code null}.
   */
  public @Nullable VirtualFile getCodeownersFile() {
    Cache c = cache;
    return c == null ? null : c.sourceFile;
  }

  private @NotNull List<CodeownersRule> getRules(@NotNull VirtualFile codeownersFile) {
    long stamp = currentStamp(codeownersFile);
    Cache existing = cache;
    if (existing != null && existing.sourceFile.equals(codeownersFile) && existing.stamp == stamp) {
      return existing.rules;
    }
    CharSequence content = readContent(codeownersFile);
    List<CodeownersRule> rules = CodeownersRuleParser.parse(content, codeownersFile);
    cache = new Cache(codeownersFile, stamp, rules);
    return rules;
  }

  private @NotNull CharSequence readContent(@NotNull VirtualFile file) {
    Document doc = FileDocumentManager.getInstance().getDocument(file);
    if (doc != null) return doc.getCharsSequence();
    try {
      return new String(file.contentsToByteArray(), file.getCharset());
    } catch (Exception ignored) {
      return "";
    }
  }

  /**
   * Uses the document stamp when an editor has the file open (catches
   * unsaved edits), and the VFS stamp otherwise.
   */
  private long currentStamp(@NotNull VirtualFile file) {
    Document doc = FileDocumentManager.getInstance().getCachedDocument(file);
    return doc != null ? doc.getModificationStamp() : file.getModificationStamp();
  }

  private record Located(@NotNull VirtualFile codeownersFile, @NotNull VirtualFile root) {
  }

  /**
   * The CODEOWNERS context for a target file: its governing CODEOWNERS file, its
   * repo-relative path, and the parsed rules.
   */
  public record FileContext(@NotNull VirtualFile codeownersFile,
                            @NotNull String relativePath,
                            @NotNull List<CodeownersRule> rules) {
  }

  private record Cache(@NotNull VirtualFile sourceFile, long stamp, @NotNull List<CodeownersRule> rules) {
  }
}

package net.wolfig.codeowls.statusbar;

import net.wolfig.codeowls.matcher.CodeownersRule;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.Collections;
import java.util.List;

/**
 * The outcome of resolving CODEOWNERS for one file: the matched rule, or
 * {@link #NONE} when no rule (or no CODEOWNERS file at all) applies.
 *
 * <p>Returned by {@link CodeownersService#resolveOwners} and consumed by the
 * status bar widget. Keeping it immutable means it is safe to pass between
 * the background read action and the UI thread.
 */
public record CodeownersOwnerResolution(@Nullable CodeownersRule rule) {

  public static final CodeownersOwnerResolution NONE = new CodeownersOwnerResolution(null);

  public boolean isEmpty() {
    return rule == null;
  }

  public @NotNull List<String> owners() {
    return rule == null ? Collections.emptyList() : rule.owners();
  }
}

package net.wolfig.codeowls.explain;

import com.intellij.openapi.actionSystem.ActionUpdateThread;
import com.intellij.openapi.actionSystem.AnActionEvent;
import com.intellij.openapi.application.ModalityState;
import com.intellij.openapi.application.ReadAction;
import com.intellij.openapi.project.DumbAwareAction;
import com.intellij.openapi.project.Project;
import com.intellij.openapi.ui.popup.JBPopupFactory;
import com.intellij.openapi.vfs.VirtualFile;
import com.intellij.ui.awt.RelativePoint;
import com.intellij.util.concurrency.AppExecutorUtil;
import net.wolfig.codeowls.action.CodeowlsFileActionTarget;
import net.wolfig.codeowls.statusbar.CodeownersService;
import org.jetbrains.annotations.NotNull;

/**
 * Action that explains <em>why</em> the selected project file has its effective
 * CODEOWNERS owner(s): shows every matching rule in evaluation order, the
 * winning rule, section inheritance, and approval counts, with click-to-navigate
 * to each rule.
 *
 * <p>Registered on the Project View and Editor context menus (and reachable from
 * Find Action). Enabled only for a single real file — not a directory, and not a
 * CODEOWNERS file itself, since explaining a CODEOWNERS file's own ownership is
 * rarely what the user wants and the status-bar widget already covers the open
 * editor.
 *
 * <p>The ownership computation reuses {@link CodeownersService#explain} on a
 * non-blocking background read action — exactly as the status-bar widget does —
 * so the EDT never parses or matches. The popup is then shown on the EDT.
 */
public final class ExplainCodeownersOwnershipAction extends DumbAwareAction {

  @Override
  public void update(@NotNull AnActionEvent e) {
    e.getPresentation().setEnabledAndVisible(CodeowlsFileActionTarget.from(e) != null);
  }

  @Override
  public @NotNull ActionUpdateThread getActionUpdateThread() {
    return ActionUpdateThread.BGT;
  }

  @Override
  public void actionPerformed(@NotNull AnActionEvent e) {
    Project project = e.getProject();
    VirtualFile file = CodeowlsFileActionTarget.from(e);
    if (project == null || file == null) return;

    // Resolve the popup anchor now, on the EDT, rather than retaining the
    // DataContext across the background computation.
    RelativePoint where = JBPopupFactory.getInstance().guessBestPopupLocation(e.getDataContext());

    ReadAction.nonBlocking(() -> CodeownersService.getInstance(project).explain(file))
            .expireWith(project)
            .finishOnUiThread(ModalityState.defaultModalityState(),
                    explanation -> OwnershipExplanationPopup.show(project, explanation, where))
            .submit(AppExecutorUtil.getAppExecutorService());
  }
}

package net.wolfig.codeowls.explain;

import com.intellij.openapi.vfs.VirtualFile;
import net.wolfig.codeowls.matcher.CodeownersRule;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;

/**
 * The full evaluation trace of CODEOWNERS ownership for one file: every rule
 * that matched it (in file / evaluation order) and which one ultimately wins.
 *
 * <p>Produced by {@code CodeownersService.explain(file)} using the exact same
 * matching pass as {@code resolveOwners(file)}, so the effective owner reported
 * here can never drift from the status-bar / owner-lookup result. Immutable, so
 * it is safe to compute under a background read action and consume on the EDT.
 *
 * @param targetFile     the file whose ownership is being explained
 * @param relativePath   {@code targetFile}'s path relative to the governing
 *                       CODEOWNERS root, or {@code null} when none governs it
 * @param codeownersFile the CODEOWNERS file that governs {@code targetFile}, or
 *                       {@code null} when no CODEOWNERS file is reachable
 * @param matchedRules   the matching rules in evaluation order; the last one is
 *                       flagged {@link MatchedRule#effective()}
 */
public record OwnershipExplanation(
        @NotNull VirtualFile targetFile,
        @Nullable String relativePath,
        @Nullable VirtualFile codeownersFile,
        @NotNull List<MatchedRule> matchedRules) {

  /**
   * Builds an explanation from the matching rules (in evaluation order),
   * marking the last — the last-match-wins winner — as effective.
   */
  public static @NotNull OwnershipExplanation of(@NotNull VirtualFile targetFile,
                                                 @NotNull String relativePath,
                                                 @NotNull VirtualFile codeownersFile,
                                                 @NotNull List<CodeownersRule> matching) {
    List<MatchedRule> matched = new ArrayList<>(matching.size());
    for (int i = 0; i < matching.size(); i++) {
      matched.add(new MatchedRule(matching.get(i), i == matching.size() - 1));
    }
    return new OwnershipExplanation(targetFile, relativePath, codeownersFile, List.copyOf(matched));
  }

  /**
   * No CODEOWNERS file governs {@code targetFile}.
   */
  public static @NotNull OwnershipExplanation noCodeowners(@NotNull VirtualFile targetFile) {
    return new OwnershipExplanation(targetFile, null, null, List.of());
  }

  /**
   * @return {@code true} when a governing CODEOWNERS file exists (even if no rule matches).
   */
  public boolean hasCodeownersFile() {
    return codeownersFile != null;
  }

  /**
   * @return {@code true} when at least one rule matches the file.
   */
  public boolean hasMatch() {
    return !matchedRules.isEmpty();
  }

  /**
   * @return the winning (effective) rule, or {@code null} when no rule matches.
   */
  public @Nullable MatchedRule effectiveRule() {
    return matchedRules.isEmpty() ? null : matchedRules.getLast();
  }

  /**
   * @return the effective owners for the file (last-match-wins), or empty when no rule matches.
   */
  public @NotNull List<String> effectiveOwners() {
    MatchedRule effective = effectiveRule();
    return effective == null ? List.of() : effective.resolvedOwners();
  }

  /**
   * @return the effective required approval count, or {@code null} when none applies.
   */
  public @Nullable Integer effectiveApprovalCount() {
    MatchedRule effective = effectiveRule();
    return effective == null ? null : effective.approvalCount();
  }
}

package net.wolfig.codeowls.navigation;

import com.intellij.codeInsight.daemon.RelatedItemLineMarkerInfo;
import com.intellij.codeInsight.daemon.RelatedItemLineMarkerProvider;
import com.intellij.codeInsight.navigation.NavigationGutterIconBuilder;
import com.intellij.icons.AllIcons;
import com.intellij.lang.ASTNode;
import com.intellij.openapi.application.ReadAction;
import com.intellij.openapi.util.NotNullLazyValue;
import com.intellij.openapi.vfs.VirtualFile;
import com.intellij.psi.PsiElement;
import com.intellij.psi.PsiFile;
import com.intellij.psi.PsiManager;
import net.wolfig.codeowls.inlay.CodeownersMatchCounter;
import net.wolfig.codeowls.lexer.CodeownersTokenTypes;
import net.wolfig.codeowls.matcher.CodeownersGlob;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import javax.swing.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.regex.Pattern;

/**
 * Adds a gutter icon to every wildcard or directory CODEOWNERS rule that lists
 * the project files the rule matches; clicking a file in the popup navigates to
 * it.
 *
 * <p>Only glob and directory patterns get a marker — an exact-path rule already
 * names its single file. The matched-file list is computed lazily (only when the
 * icon is clicked), so the daemon pass that places the marker stays cheap; the
 * click reuses {@link CodeownersMatchCounter}'s project walk and
 * {@link CodeownersGlob} matching. The list is capped at {@link #MAX_TARGETS}
 * to keep the popup responsive on broad rules like {@code /src/**}.
 */
public final class CodeownersMatchedFilesLineMarkerProvider extends RelatedItemLineMarkerProvider {

  static final int MAX_TARGETS = 1000;

  private static @NotNull Collection<? extends PsiElement> collectMatchedFiles(@NotNull PsiFile codeownersFile,
                                                                               @NotNull String pattern) {
    VirtualFile vf = codeownersFile.getVirtualFile();
    VirtualFile root = CodeownersMatchCounter.projectRoot(vf);
    if (root == null) return List.of();

    PsiManager psiManager = PsiManager.getInstance(codeownersFile.getProject());
    List<PsiElement> files = new ArrayList<>();
    for (String path : matchingPaths(pattern, CodeownersMatchCounter.collectProjectFilePaths(root))) {
      VirtualFile child = root.findFileByRelativePath(path);
      if (child == null || !child.isValid()) continue;
      PsiFile psi = psiManager.findFile(child);
      if (psi != null) files.add(psi);
    }
    return files;
  }

  /**
   * The (up to {@link #MAX_TARGETS}) project paths matched by {@code pattern}.
   * Pure, so the selection logic is unit-tested without the IntelliJ platform.
   */
  static @NotNull List<String> matchingPaths(@NotNull String pattern, @NotNull List<String> projectPaths) {
    Pattern compiled = CodeownersGlob.compile(pattern);
    List<String> matched = new ArrayList<>();
    for (String path : projectPaths) {
      if (compiled.matcher(path).matches()) {
        matched.add(path);
        if (matched.size() >= MAX_TARGETS) break;
      }
    }
    return matched;
  }

  @Override
  protected void collectNavigationMarkers(@NotNull PsiElement element,
                                          @NotNull Collection<? super RelatedItemLineMarkerInfo<?>> result) {
    ASTNode node = element.getNode();
    if (node == null || node.getElementType() != CodeownersTokenTypes.PATTERN) return;

    String pattern = element.getText();
    if (pattern == null || !CodeownersMatchCounter.isGlobOrDirectoryPattern(pattern)) return;

    PsiFile codeownersFile = element.getContainingFile();
    if (codeownersFile == null) return;

    NotNullLazyValue<Collection<? extends PsiElement>> targets =
            NotNullLazyValue.lazy(() -> ReadAction.compute(() -> collectMatchedFiles(codeownersFile, pattern)));

    result.add(NavigationGutterIconBuilder.create(AllIcons.Nodes.Folder)
            .setTargets(targets)
            .setTooltipText("Files matched by this CODEOWNERS rule")
            .setPopupTitle("Files Matched by " + pattern)
            .setEmptyPopupText("No files match this rule")
            .createLineMarkerInfo(element));
  }

  @Override
  public @NotNull String getName() {
    return "CODEOWNERS rule matched files";
  }

  @Override
  public @Nullable Icon getIcon() {
    return AllIcons.Nodes.Folder;
  }
}

package net.wolfig.codeowls.inlay;

import com.intellij.openapi.vfs.VirtualFile;
import com.intellij.psi.PsiFile;
import com.intellij.psi.util.CachedValueProvider;
import com.intellij.psi.util.CachedValuesManager;
import com.intellij.psi.util.PsiModificationTracker;
import net.wolfig.codeowls.matcher.CodeownersRule;
import net.wolfig.codeowls.matcher.CodeownersRuleParser;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.*;

/**
 * Counts how many project files each CODEOWNERS rule matches.
 *
 * <p>The result is cached per CODEOWNERS {@link PsiFile} via
 * {@link CachedValuesManager} and invalidated on PSI changes. The inlay-hint
 * collector calls into this class on every pass; without the cache it would
 * re-walk the project tree and re-run every rule on every repaint.
 *
 * <p>Single-file (exact-path) rules and obviously irrelevant lines (comments,
 * empty lines, malformed lines, section headers — anything {@link
 * CodeownersRuleParser} doesn't surface as a rule) are skipped: a "1 file"
 * hint on a rule that already names a specific path adds nothing.
 *
 * <p>For tests and reuse the heavy lifting lives in
 * {@link #computeCountsByLine(CharSequence, VirtualFile, List)} — a pure
 * function that takes the CODEOWNERS text and a precomputed list of project
 * file paths.
 */
public final class CodeownersMatchCounter {

  /**
   * Directory names skipped when walking project files. Matches the path completion list.
   */
  static final Set<String> IGNORED_DIRECTORY_NAMES = Set.of(
          ".git", ".idea", ".gradle", "node_modules", "build", "dist", "target", "out");

  private CodeownersMatchCounter() {
  }

  /**
   * @return a (line → match-count) map for {@code codeownersFile}, cached on
   * the PSI file and invalidated on any PSI modification. Lines that aren't
   * glob-style rules (comments, headers, malformed lines, exact-path rules)
   * are absent from the map rather than reported as zero.
   */
  public static @NotNull Map<Integer, Integer> countsByLine(@NotNull PsiFile codeownersFile) {
    return CachedValuesManager.getCachedValue(codeownersFile, () -> {
      Map<Integer, Integer> counts = compute(codeownersFile);
      return CachedValueProvider.Result.create(counts,
              codeownersFile, PsiModificationTracker.MODIFICATION_COUNT);
    });
  }

  private static @NotNull Map<Integer, Integer> compute(@NotNull PsiFile codeownersFile) {
    VirtualFile vf = codeownersFile.getVirtualFile();
    VirtualFile root = projectRoot(vf);
    if (root == null) return Map.of();
    List<String> paths = collectProjectFilePaths(root);
    return computeCountsByLine(codeownersFile.getViewProvider().getContents(), vf, paths);
  }

  /**
   * Pure-logic core, exposed for tests. Parses {@code codeownersText} and,
   * for each glob-style rule, counts how many of {@code projectFilePaths}
   * (forward-slash, no leading {@code /}) the rule matches.
   */
  static @NotNull Map<Integer, Integer> computeCountsByLine(@NotNull CharSequence codeownersText,
                                                            @Nullable VirtualFile sourceForRules,
                                                            @NotNull List<String> projectFilePaths) {
    if (codeownersText.isEmpty()) return Map.of();
    List<CodeownersRule> rules = CodeownersRuleParser.parse(codeownersText, sourceForRules);
    Map<Integer, Integer> result = new HashMap<>();
    for (CodeownersRule rule : rules) {
      // Only emit hints for patterns whose match count is non-trivial: a glob
      // (contains *, ?, [, ]) or a directory pattern (ends with /). Anchored
      // file paths and bare basenames almost always resolve to a single file,
      // so the "// 1 file" hint just adds visual noise.
      if (!isGlobOrDirectoryPattern(rule.pattern())) continue;
      int matches = 0;
      for (String path : projectFilePaths) {
        if (rule.matches(path)) matches++;
      }
      result.put(rule.lineNumber(), matches);
    }
    return result;
  }

  /**
   * The directory CODEOWNERS patterns are written against. Mirrors the
   * heuristic used by {@code CodeownersPathCompletionProvider}: a CODEOWNERS
   * file under {@code .github/}, {@code .gitlab/}, or {@code docs/} resolves
   * to its grandparent; otherwise its parent.
   */
  public static @Nullable VirtualFile projectRoot(@Nullable VirtualFile codeownersFile) {
    if (codeownersFile == null) return null;
    VirtualFile parent = codeownersFile.getParent();
    if (parent == null) return null;
    String name = parent.getName();
    if (name.equals(".github") || name.equals(".gitlab") || name.equals("docs")) {
      VirtualFile gp = parent.getParent();
      return gp != null ? gp : parent;
    }
    return parent;
  }

  /**
   * Collect every regular file under {@code root}, returned as project-relative
   * forward-slash paths (no leading {@code /}). Ignored build/VCS folders are
   * skipped before recursion. Package-private for tests.
   */
  public static @NotNull List<String> collectProjectFilePaths(@NotNull VirtualFile root) {
    List<String> result = new ArrayList<>();
    walk(root, "", result);
    return result;
  }

  /**
   * @return {@code true} if {@code pattern} is either a directory pattern
   * (ends with {@code /}) or contains any glob metacharacter
   * ({@code *}, {@code ?}, {@code [}, {@code ]}). Patterns that satisfy
   * neither condition (anchored file paths and bare basenames) are excluded
   * from the inlay hint — they're either guaranteed to match a single file
   * or, in practice, almost always do.
   */
  public static boolean isGlobOrDirectoryPattern(@NotNull String pattern) {
    if (pattern.isEmpty()) return false;
    if (pattern.endsWith("/")) return true;
    for (int i = 0; i < pattern.length(); i++) {
      char c = pattern.charAt(i);
      if (c == '*' || c == '?' || c == '[' || c == ']') return true;
    }
    return false;
  }

  private static void walk(@NotNull VirtualFile dir, @NotNull String prefix, @NotNull List<String> out) {
    for (VirtualFile child : dir.getChildren()) {
      if (!child.isValid()) continue;
      String name = child.getName();
      String next = prefix.isEmpty() ? name : prefix + "/" + name;
      if (child.isDirectory()) {
        if (IGNORED_DIRECTORY_NAMES.contains(name)) continue;
        walk(child, next, out);
      } else {
        out.add(next);
      }
    }
  }
}

package net.wolfig.codeowls.refactoring;

import com.intellij.lang.ASTNode;
import com.intellij.openapi.actionSystem.ActionUpdateThread;
import com.intellij.openapi.actionSystem.AnActionEvent;
import com.intellij.openapi.actionSystem.CommonDataKeys;
import com.intellij.openapi.editor.Editor;
import com.intellij.openapi.project.DumbAwareAction;
import com.intellij.openapi.project.Project;
import com.intellij.psi.PsiElement;
import com.intellij.psi.PsiFile;
import net.wolfig.codeowls.lang.CodeownersLanguage;
import net.wolfig.codeowls.matcher.CodeownersRuleParser;
import net.wolfig.codeowls.refactoring.CodeownersOwnerRefactoring.OwnerToken;
import net.wolfig.codeowls.refactoring.CodeownersOwnerRefactoring.Plan;
import net.wolfig.codeowls.refactoring.CodeownersOwnerRefactoring.SectionRange;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

/**
 * "Refactor Owner…" — replaces the owner under the caret with another one,
 * either throughout the enclosing GitLab section or throughout the whole
 * CODEOWNERS file.
 *
 * <p>Enablement is decided on the PSI: the leaf at the caret must carry one of
 * the lexer's owner element types. Everything else in a CODEOWNERS file —
 * patterns, comments, section names, approval counts, whitespace — has a
 * different element type, so the action simply does not appear there, and it is
 * inert in every other language.
 *
 * <p>The replacement itself is planned by {@link CodeownersOwnerRefactoring} and
 * executed by {@link CodeownersOwnerRefactoringCommand} as a single undoable
 * command. The same entry point backs {@link CodeownersOwnerRenameHandler}, so
 * Shift+F6 on an owner opens the same dialog.
 */
public final class RefactorCodeownersOwnerAction extends DumbAwareAction {

  /**
   * The owner element at the caret, or {@code null} when the caret is not on an
   * owner (or the file is not a CODEOWNERS file).
   *
   * <p>A caret sitting immediately behind an owner still counts, so
   * {@code @alice<caret>} resolves like {@code @al<caret>ice}. Must be called
   * under a read action.
   */
  public static @Nullable PsiElement ownerElementAt(@Nullable Editor editor, @Nullable PsiFile file) {
    if (editor == null || file == null || !file.getLanguage().is(CodeownersLanguage.INSTANCE)) return null;

    int offset = editor.getCaretModel().getOffset();
    PsiElement element = ownerLeafAt(file, offset);
    return element != null ? element : (offset > 0 ? ownerLeafAt(file, offset - 1) : null);
  }

  private static @Nullable PsiElement ownerLeafAt(@NotNull PsiFile file, int offset) {
    PsiElement leaf = file.findElementAt(offset);
    if (leaf == null) return null;
    ASTNode node = leaf.getNode();
    return node != null && CodeownersRuleParser.isOwnerToken(node.getElementType()) ? leaf : null;
  }

  /**
   * Asks for a replacement owner and a scope, then performs the refactoring.
   * Does nothing when the caret is not on an owner, or when the user cancels.
   */
  public static void refactorOwnerAtCaret(@NotNull Project project,
                                          @Nullable Editor editor,
                                          @Nullable PsiFile file) {
    if (editor == null || file == null || ownerElementAt(editor, file) == null) return;

    // The PSI decided that this is an owner; the token itself is then read back
    // from the document the edit will target, so plan offsets and document
    // offsets can never disagree (e.g. over uncommitted PSI).
    CharSequence content = editor.getDocument().getImmutableCharSequence();
    OwnerToken owner = CodeownersOwnerRefactoring.ownerTokenAt(content, editor.getCaretModel().getOffset());
    if (owner == null) return;

    SectionRange section = CodeownersOwnerRefactoring.sectionAt(content, owner.startOffset());
    RefactorCodeownersOwnerDialog dialog =
            new RefactorCodeownersOwnerDialog(project, content, owner, section, file.getName());
    if (!dialog.showAndGet()) return;

    Plan plan = dialog.plan();
    CodeownersOwnerRefactoringCommand.execute(project, file, editor.getDocument(), plan);
  }

  @Override
  public void update(@NotNull AnActionEvent e) {
    boolean available = e.getProject() != null
            && ownerElementAt(e.getData(CommonDataKeys.EDITOR), e.getData(CommonDataKeys.PSI_FILE)) != null;
    e.getPresentation().setEnabledAndVisible(available);
  }

  @Override
  public @NotNull ActionUpdateThread getActionUpdateThread() {
    return ActionUpdateThread.BGT;
  }

  @Override
  public void actionPerformed(@NotNull AnActionEvent e) {
    Project project = e.getProject();
    if (project == null) return;
    refactorOwnerAtCaret(project, e.getData(CommonDataKeys.EDITOR), e.getData(CommonDataKeys.PSI_FILE));
  }
}

package net.wolfig.codeowls.matcher;

import com.intellij.openapi.vfs.VirtualFile;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.List;
import java.util.regex.Pattern;

/**
 * A single parsed CODEOWNERS rule: {@code pattern owner1 owner2 …}.
 *
 * <p>The {@link #compiledPattern} is a {@link Pattern} built by
 * {@link CodeownersGlob#compile(String)} that decides whether a given
 * project-relative file path is matched by this rule's glob.
 *
 * @param pattern         the raw glob exactly as it appears in the file
 * @param owners          owners listed after the pattern, in source order
 * @param compiledPattern compiled glob → regex (anchored, gitignore-style)
 * @param sourceFile      the CODEOWNERS file the rule was read from, or
 *                        {@code null} if it has been deleted since parsing
 * @param lineNumber      0-based line number of the rule in the source file
 * @param approvalCount   number of approvals required by the rule's enclosing
 *                        GitLab section (e.g. {@code [Backend][2]}), or
 *                        {@code null} when the rule is in no section or the
 *                        section declares no approval count
 * @param section         the enclosing GitLab section header, or {@code null}
 *                        when the rule is in no section. Retained purely so an
 *                        ownership explanation can describe inheritance; the
 *                        effective {@link #owners()} / {@link #approvalCount()}
 *                        are already resolved
 * @param ownersInherited {@code true} when {@link #owners()} were inherited from
 *                        {@link #section}'s default owners because the rule
 *                        declared none of its own
 */
public record CodeownersRule(
        @NotNull String pattern,
        @NotNull List<String> owners,
        @NotNull Pattern compiledPattern,
        @Nullable VirtualFile sourceFile,
        int lineNumber,
        @Nullable Integer approvalCount,
        @Nullable CodeownersSection section,
        boolean ownersInherited) {

  /**
   * Convenience constructor for a rule outside any GitLab section.
   */
  public CodeownersRule(@NotNull String pattern, @NotNull List<String> owners,
                        @NotNull Pattern compiledPattern, @Nullable VirtualFile sourceFile,
                        int lineNumber, @Nullable Integer approvalCount) {
    this(pattern, owners, compiledPattern, sourceFile, lineNumber, approvalCount, null, false);
  }

  /**
   * Convenience constructor for a rule with no section approval count.
   */
  public CodeownersRule(@NotNull String pattern, @NotNull List<String> owners,
                        @NotNull Pattern compiledPattern, @Nullable VirtualFile sourceFile,
                        int lineNumber) {
    this(pattern, owners, compiledPattern, sourceFile, lineNumber, null);
  }

  /**
   * @return {@code true} if {@code relativePath} (forward-slash, no leading /) is matched by this rule.
   */
  public boolean matches(@NotNull String relativePath) {
    return compiledPattern.matcher(relativePath).matches();
  }
}

package net.wolfig.codeowls.matcher;

import com.intellij.openapi.vfs.VirtualFile;
import com.intellij.psi.TokenType;
import com.intellij.psi.tree.IElementType;
import net.wolfig.codeowls.lexer.CodeownersLexer;
import net.wolfig.codeowls.lexer.CodeownersTokenTypes;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Extracts {@link CodeownersRule}s from CODEOWNERS file content by driving the
 * shared {@link CodeownersLexer} and grouping pattern + owner tokens on the
 * same line.
 *
 * <p>This is the only place where lexer tokens are translated into the rule
 * model — keeping it here avoids duplicating the lexer's awareness of token
 * categories elsewhere.
 *
 * <p>GitLab section headers may declare <em>default owners</em> on the header
 * line, e.g. {@code [Backend][2] @org/backend @alice}. Those owners apply to
 * every rule in the section that does not list owners of its own; a rule that
 * does list owners overrides the default entirely. A section's scope runs from
 * its header to the next header (or end of file), and a header with no owners
 * clears any previously inherited default. The owners stored on each
 * {@link CodeownersRule} are therefore the <em>effective</em> owners, after
 * inheritance has been applied.
 *
 * <p>A section's optional approval count ({@code [Backend][2]}) is likewise
 * carried onto every rule in that section as {@link CodeownersRule#approvalCount()}.
 */
public final class CodeownersRuleParser {

  private CodeownersRuleParser() {
  }

  /**
   * Parse {@code content}. {@code source} is attached to each rule for navigation.
   */
  public static @NotNull List<CodeownersRule> parse(@NotNull CharSequence content,
                                                    @Nullable VirtualFile source) {
    if (content.isEmpty()) return Collections.emptyList();

    CodeownersLexer lexer = new CodeownersLexer();
    lexer.start(content, 0, content.length(), 0);

    List<CodeownersRule> rules = new ArrayList<>();
    String pendingPattern = null;
    int pendingLine = -1;
    List<String> pendingOwners = null;

    // Default owners declared on the current section header line, inherited by
    // rules in the section that name no owners of their own. Reset by each new
    // section header.
    List<String> sectionDefaultOwners = Collections.emptyList();
    // Approval count declared on the current section header (e.g. [Backend][2]),
    // or null when the section declares none. Also reset by each new header.
    Integer sectionApprovalCount = null;
    // The current section header as a whole, or null before the first header.
    // Carried onto each rule so an explanation can describe inheritance.
    CodeownersSection currentSection = null;
    // While true we are accumulating the section header line; its owners become
    // the section default and its [N] becomes the approval count once it ends.
    boolean inSectionHeader = false;
    List<String> headerOwners = null;
    Integer headerApprovalCount = null;
    String headerName = null;
    boolean headerOptional = false;

    while (lexer.getTokenType() != null) {
      IElementType type = lexer.getTokenType();
      int start = lexer.getTokenStart();
      int end = lexer.getTokenEnd();

      if (type == CodeownersTokenTypes.SECTION_HEADER) {
        if (pendingPattern != null) {
          rules.add(buildRule(pendingPattern, pendingOwners, sectionDefaultOwners, source, pendingLine, sectionApprovalCount, currentSection));
          pendingPattern = null;
          pendingOwners = null;
        }
        // Begin collecting the new section header; the previous section's
        // default owners and approval count no longer apply once a header is seen.
        String headerText = content.subSequence(start, end).toString();
        headerOptional = headerText.startsWith("^");
        headerName = sectionName(headerText);
        inSectionHeader = true;
        headerOwners = new ArrayList<>();
        headerApprovalCount = null;
      } else if (type == CodeownersTokenTypes.PATTERN) {
        if (pendingPattern != null) {
          rules.add(buildRule(pendingPattern, pendingOwners, sectionDefaultOwners, source, pendingLine, sectionApprovalCount, currentSection));
        }
        pendingPattern = content.subSequence(start, end).toString();
        pendingLine = lineNumberOf(content, start);
        pendingOwners = new ArrayList<>();
      } else if (type == CodeownersTokenTypes.APPROVAL_COUNT && inSectionHeader) {
        headerApprovalCount = parseApprovalCount(content.subSequence(start, end).toString());
      } else if (isOwnerToken(type)) {
        if (inSectionHeader) {
          headerOwners.add(content.subSequence(start, end).toString());
        } else if (pendingPattern != null) {
          pendingOwners.add(content.subSequence(start, end).toString());
        }
      } else if (type == TokenType.WHITE_SPACE && containsNewline(content, start, end)) {
        if (inSectionHeader) {
          sectionDefaultOwners = List.copyOf(headerOwners);
          sectionApprovalCount = headerApprovalCount;
          currentSection = new CodeownersSection(
                  headerName != null ? headerName : "",
                  headerOptional, sectionDefaultOwners, sectionApprovalCount);
          inSectionHeader = false;
          headerOwners = null;
          headerApprovalCount = null;
          headerName = null;
          headerOptional = false;
        } else if (pendingPattern != null) {
          rules.add(buildRule(pendingPattern, pendingOwners, sectionDefaultOwners, source, pendingLine, sectionApprovalCount, currentSection));
          pendingPattern = null;
          pendingOwners = null;
        }
      }

      lexer.advance();
    }
    if (pendingPattern != null) {
      rules.add(buildRule(pendingPattern, pendingOwners, sectionDefaultOwners, source, pendingLine, sectionApprovalCount, currentSection));
    }
    return rules;
  }

  /**
   * Extracts the name from a {@code SECTION_HEADER} token such as
   * {@code [Backend]} or {@code ^[Backend]} — the text between the brackets.
   */
  public static @NotNull String sectionName(@NotNull String headerText) {
    int open = headerText.indexOf('[');
    int close = headerText.indexOf(']', open + 1);
    if (open < 0 || close < 0) return "";
    return headerText.substring(open + 1, close).trim();
  }

  /**
   * Parses the integer inside an {@code APPROVAL_COUNT} token (e.g. {@code [2]}),
   * returning {@code null} for a missing or non-numeric value.
   */
  private static @Nullable Integer parseApprovalCount(@NotNull String token) {
    String t = token.trim();
    if (t.startsWith("[")) t = t.substring(1);
    if (t.endsWith("]")) t = t.substring(0, t.length() - 1);
    try {
      int n = Integer.parseInt(t.trim());
      return n >= 0 ? n : null;
    } catch (NumberFormatException ignored) {
      return null;
    }
  }

  /**
   * Builds a rule, applying section inheritance: a rule that declares no owners
   * of its own takes the enclosing section's default owners, and that fact is
   * recorded via {@link CodeownersRule#ownersInherited()} for later explanation.
   */
  private static @NotNull CodeownersRule buildRule(@NotNull String pattern,
                                                   @NotNull List<String> ruleOwners,
                                                   @NotNull List<String> sectionDefaultOwners,
                                                   @Nullable VirtualFile source,
                                                   int lineNumber,
                                                   @Nullable Integer approvalCount,
                                                   @Nullable CodeownersSection section) {
    boolean inherited = ruleOwners.isEmpty() && !sectionDefaultOwners.isEmpty();
    List<String> owners = inherited ? sectionDefaultOwners : ruleOwners;
    return new CodeownersRule(
            pattern,
            List.copyOf(owners),
            CodeownersGlob.compile(pattern),
            source,
            lineNumber,
            approvalCount,
            section,
            inherited);
  }

  /**
   * Whether {@code type} is one of the lexer's owner categories — user, team,
   * role or e-mail. Shared so that features working on owner tokens (owner
   * refactoring, for one) classify them exactly as the rule model does.
   */
  public static boolean isOwnerToken(IElementType type) {
    return type == CodeownersTokenTypes.USER_OWNER
            || type == CodeownersTokenTypes.TEAM_OWNER
            || type == CodeownersTokenTypes.ROLE_OWNER
            || type == CodeownersTokenTypes.EMAIL_OWNER;
  }

  private static boolean containsNewline(CharSequence content, int start, int end) {
    for (int i = start; i < end; i++) {
      char c = content.charAt(i);
      if (c == '\n' || c == '\r') return true;
    }
    return false;
  }

  private static int lineNumberOf(CharSequence content, int offset) {
    int line = 0;
    for (int i = 0; i < offset && i < content.length(); i++) {
      if (content.charAt(i) == '\n') line++;
    }
    return line;
  }
}

package net.wolfig.codeowls.lexer;

import com.intellij.psi.tree.IElementType;
import net.wolfig.codeowls.lang.CodeownersLanguage;

/**
 * {@link IElementType} constants for every token category produced by
 * {@link CodeownersLexer}.
 */
public final class CodeownersTokenTypes {

  /**
   * {@code # comment text}
   */
  public static final IElementType COMMENT =
          new IElementType("COMMENT", CodeownersLanguage.INSTANCE);

  /**
   * File-glob pattern that starts a rule line, e.g. {@code *.java} or {@code /src/**}.
   */
  public static final IElementType PATTERN =
          new IElementType("PATTERN", CodeownersLanguage.INSTANCE);

  /**
   * Individual GitHub/GitLab user owner, e.g. {@code @alice}.
   */
  public static final IElementType USER_OWNER =
          new IElementType("USER_OWNER", CodeownersLanguage.INSTANCE);

  /**
   * GitHub/GitLab team owner (contains a slash), e.g. {@code @org/backend}.
   */
  public static final IElementType TEAM_OWNER =
          new IElementType("TEAM_OWNER", CodeownersLanguage.INSTANCE);

  /**
   * GitLab role owner, e.g. {@code @@maintainer}, {@code @@developer}, {@code @@developers}.
   */
  public static final IElementType ROLE_OWNER =
          new IElementType("ROLE_OWNER", CodeownersLanguage.INSTANCE);

  /**
   * E-mail owner, e.g. {@code alice@example.com}.
   */
  public static final IElementType EMAIL_OWNER =
          new IElementType("EMAIL_OWNER", CodeownersLanguage.INSTANCE);

  /**
   * GitLab section header, e.g. {@code [Backend]} or {@code ^[Backend]} (optional).
   */
  public static final IElementType SECTION_HEADER =
          new IElementType("SECTION_HEADER", CodeownersLanguage.INSTANCE);

  /**
   * GitLab optional approval count that follows a section header, e.g. {@code [2]}.
   */
  public static final IElementType APPROVAL_COUNT =
          new IElementType("APPROVAL_COUNT", CodeownersLanguage.INSTANCE);

  /**
   * Token that does not fit any legal CODEOWNERS syntax.
   */
  public static final IElementType BAD_CHARACTER =
          new IElementType("BAD_CHARACTER", CodeownersLanguage.INSTANCE);

  private CodeownersTokenTypes() {
  }
}

package net.wolfig.codeowls.refactoring;

import com.intellij.openapi.actionSystem.ActionUpdateThread;
import com.intellij.openapi.actionSystem.AnActionEvent;
import com.intellij.openapi.actionSystem.CommonDataKeys;
import com.intellij.openapi.actionSystem.DataContext;
import com.intellij.openapi.actionSystem.impl.SimpleDataContext;
import com.intellij.openapi.application.ReadAction;
import com.intellij.openapi.fileTypes.PlainTextFileType;
import com.intellij.testFramework.TestActionEvent;
import com.intellij.testFramework.fixtures.CodeInsightTestFixture;
import com.intellij.testFramework.fixtures.IdeaProjectTestFixture;
import com.intellij.testFramework.fixtures.IdeaTestFixtureFactory;
import com.intellij.testFramework.fixtures.TestFixtureBuilder;
import net.wolfig.codeowls.lang.CodeownersFileType;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests the enablement contract of "Refactor Owner…": it appears when — and
 * only when — the caret sits on a real CODEOWNERS owner token.
 *
 * <p>The caret is placed with the fixture's {@code <caret>} marker, and
 * enablement is probed with a synthetic {@link TestActionEvent}, exactly as the
 * IDE would call {@code update}.
 *
 * <p>Tests follow the Arrange / Act / Assert pattern.
 */
public class RefactorCodeownersOwnerActionTest {

  private CodeInsightTestFixture fixture;

  @Before
  public void setUp() throws Exception {
    IdeaTestFixtureFactory factory = IdeaTestFixtureFactory.getFixtureFactory();
    TestFixtureBuilder<IdeaProjectTestFixture> builder =
            factory.createLightFixtureBuilder(getClass().getName());
    fixture = factory.createCodeInsightFixture(builder.getFixture());
    fixture.setUp();
  }

  @After
  public void tearDown() throws Exception {
    if (fixture != null) {
      fixture.tearDown();
      fixture = null;
    }
  }

  /**
   * Configures a CODEOWNERS file with the given {@code <caret>} position and
   * reports whether the action would be offered there.
   */
  private boolean isEnabledAtCaret(String codeownersContent) {
    fixture.configureByText(CodeownersFileType.INSTANCE, codeownersContent);
    return isEnabled();
  }

  private boolean isEnabled() {
    DataContext context = SimpleDataContext.builder()
            .add(CommonDataKeys.PROJECT, fixture.getProject())
            .add(CommonDataKeys.EDITOR, fixture.getEditor())
            .add(CommonDataKeys.PSI_FILE, fixture.getFile())
            .build();
    RefactorCodeownersOwnerAction action = new RefactorCodeownersOwnerAction();
    AnActionEvent event = TestActionEvent.createTestEvent(action, context);
    return ReadAction.compute(() -> {
      action.update(event);
      return event.getPresentation().isEnabledAndVisible();
    });
  }

  @Test
  public void update_caretOnUserOwner_isEnabled() {
    assertTrue(isEnabledAtCaret("/api/** @al<caret>ice\n"));
  }

  @Test
  public void update_caretOnTeamOwner_isEnabled() {
    assertTrue(isEnabledAtCaret("/api/** @org/<caret>backend\n"));
  }

  @Test
  public void update_caretOnRoleOwner_isEnabled() {
    assertTrue(isEnabledAtCaret("/api/** @@main<caret>tainer\n"));
  }

  @Test
  public void update_caretOnEmailOwner_isEnabled() {
    assertTrue(isEnabledAtCaret("/api/** alice@exa<caret>mple.com\n"));
  }

  @Test
  public void update_caretOnSectionDefaultOwner_isEnabled() {
    assertTrue(isEnabledAtCaret("[Backend][2] @al<caret>ice\n/api/**\n"));
  }

  @Test
  public void update_caretRightAfterOwner_isEnabled() {
    // Arrange / Act / Assert — the caret at the end of the token still counts.
    assertTrue(isEnabledAtCaret("/api/** @alice<caret>\n"));
  }

  @Test
  public void update_caretOnPattern_isDisabled() {
    assertFalse(isEnabledAtCaret("/api<caret>/** @alice\n"));
  }

  @Test
  public void update_caretOnComment_isDisabled() {
    assertFalse(isEnabledAtCaret("# ask @al<caret>ice first\n/api/** @alice\n"));
  }

  @Test
  public void update_caretOnSectionName_isDisabled() {
    assertFalse(isEnabledAtCaret("[Back<caret>end]\n/api/** @alice\n"));
  }

  @Test
  public void update_caretOnApprovalCount_isDisabled() {
    assertFalse(isEnabledAtCaret("[Backend][<caret>2] @alice\n/api/**\n"));
  }

  @Test
  public void update_caretOnWhitespace_isDisabled() {
    assertFalse(isEnabledAtCaret("/api/**\n<caret>\n/ui/** @alice\n"));
  }

  @Test
  public void update_caretOnArbitraryText_isDisabled() {
    // Arrange — "hello" in owner position is a bad character, not an owner.
    assertFalse(isEnabledAtCaret("/api/** hel<caret>lo\n"));
  }

  @Test
  public void update_nonCodeownersFile_isDisabled() {
    // Arrange — the same text in a plain-text file must not offer the action.
    fixture.configureByText(PlainTextFileType.INSTANCE, "/api/** @al<caret>ice\n");

