    int n = rules.size();
    if (n == 0) return List.of();

    boolean[] analyzable = new boolean[n];
    for (int i = 0; i < n; i++) analyzable[i] = isAnalyzable(rules.get(i).pattern());

    boolean[] matchedAny = new boolean[n];
    boolean[] everWinner = new boolean[n];
